    text = path.read_text(encoding="utf-8")
    if not pattern:
        return text
    m = re.search(pattern, text)
    if not m:
        raise ValueError(f"requirements pattern {pattern!r} not found in {path}")
    start = m.start()
    level = len(text[start:]) - len(text[start:].lstrip("#"))
