        # '**Trigger:** step-4 matrix walk', or as a list item ('- fault:
        # F-13'). A plain 'Fault: ...' line is prose, and the first field of
        # each kind in a question wins.
        odc = re.match(r"^(?:\*\*(fault|trigger):\*\*|\*\*(fault|trigger)\*\*:|[-*][ \t]+(fault|trigger):)"
                       r"[ \t]*(.*)$", line.strip(), re.I)
