            label = (odc.group(1) or odc.group(2) or odc.group(3)).lower()
            value = odc.group(4)
            if label == "fault" and "fault" not in current:
                current["fault"] = re.findall(r"F-\d{2}\b", value)
            elif label == "trigger" and "trigger" not in current:
